        int queryStart = requestPath.IndexOf('?', StringComparison.Ordinal);
        string path = queryStart < 0 ? requestPath : requestPath[..queryStart];
        foreach (Endpoint endpoint in Endpoints)
        {
            if (string.Equals(endpoint.Method, method, StringComparison.OrdinalIgnoreCase) && Matches(endpoint.Path, path))
            {
                return true;
            }
        }

        return false;
    }

    internal static bool ContainsOperationId(string operationId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(operationId);
        foreach (Endpoint endpoint in Endpoints)
        {
            if (string.Equals(endpoint.OperationId, operationId, StringComparison.Ordinal))
            {
                return true;
            }
        }

        return false;
    }

    internal static bool AllowsSuccessStatusCode(string method, string requestPath, int statusCode)
    {
        Endpoint? endpoint = Find(method, requestPath);
        return endpoint is not null && Array.IndexOf(endpoint.Value.SuccessStatusCodes, statusCode) >= 0;
    }

    internal static bool AcceptsRequestContentType(string method, string requestPath, string contentType)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(contentType);
        Endpoint? endpoint = Find(method, requestPath);
        return endpoint is not null && Array.Exists(endpoint.Value.RequestContentTypes, item => string.Equals(item, contentType, StringComparison.OrdinalIgnoreCase));
    }

    internal static bool ProducesResponseContentType(string method, string requestPath, string contentType)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(contentType);
        Endpoint? endpoint = Find(method, requestPath);
        return endpoint is not null && Array.Exists(endpoint.Value.ResponseContentTypes, item => string.Equals(item, contentType, StringComparison.OrdinalIgnoreCase));
    }

    private static Endpoint? Find(string method, string requestPath)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(method);
        ArgumentException.ThrowIfNullOrWhiteSpace(requestPath);
        int queryStart = requestPath.IndexOf('?', StringComparison.Ordinal);
        string path = queryStart < 0 ? requestPath : requestPath[..queryStart];
        foreach (Endpoint endpoint in Endpoints)
        {
            if (string.Equals(endpoint.Method, method, StringComparison.OrdinalIgnoreCase) && Matches(endpoint.Path, path))
            {
                return endpoint;
            }
        }

        return null;
    }

    private static bool Matches(string template, string path)
    {
        string[] expected = template.Trim('/').Split('/', StringSplitOptions.RemoveEmptyEntries);
        string[] actual = path.Trim('/').Split('/', StringSplitOptions.RemoveEmptyEntries);
        if (expected.Length != actual.Length)
        {
            return false;
        }

        for (int index = 0; index < expected.Length; index++)
        {
            bool parameter = expected[index].StartsWith('{') && expected[index].EndsWith('}');
            if (!parameter && !string.Equals(expected[index], actual[index], StringComparison.Ordinal))
            {
                return false;
            }
        }

        return true;
    }

    private readonly record struct Endpoint(
        string Method,
        string Path,
        string OperationId,
        int[] SuccessStatusCodes,
        string[] RequestContentTypes,
        string[] ResponseContentTypes);
}
